  function drawPlot(p){
    var svg = document.getElementById("plotSVG");
    var padL = 46, padT = 34, padR = 18, padB = 30;
    var availW = 360 - padL - padR, availH = 210 - padT - padB;
    var scale = Math.min(availW / p.w, availH / p.d);
    var w = p.w * scale, h = p.d * scale;
    var x = padL + (availW - w)/2, y = padT + (availH - h)/2;

    var ns = "http://www.w3.org/2000/svg";
    svg.innerHTML =
      '<title>Plot dimension drawing</title>'+
      // plot rectangle
      '<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" fill="#EAF1FA" stroke="#003478" stroke-width="1.5"/>'+
      // hatch to suggest built footprint
      '<rect x="'+(x+6)+'" y="'+(y+6)+'" width="'+(w-12)+'" height="'+(h-12)+'" fill="none" stroke="#1A6FC4" stroke-width="1" stroke-dasharray="4 3"/>'+
      // top dimension line
      '<line x1="'+x+'" y1="'+(y-16)+'" x2="'+(x+w)+'" y2="'+(y-16)+'" stroke="#1A6FC4" stroke-width="1"/>'+
      '<line x1="'+x+'" y1="'+(y-21)+'" x2="'+x+'" y2="'+(y-11)+'" stroke="#1A6FC4" stroke-width="1"/>'+
      '<line x1="'+(x+w)+'" y1="'+(y-21)+'" x2="'+(x+w)+'" y2="'+(y-11)+'" stroke="#1A6FC4" stroke-width="1"/>'+
      '<text x="'+(x+w/2)+'" y="'+(y-22)+'" text-anchor="middle" font-family="IBM Plex Mono, monospace" font-size="11" fill="#003478">'+p.w+"'"+'</text>'+
      // left dimension line
      '<line x1="'+(x-18)+'" y1="'+y+'" x2="'+(x-18)+'" y2="'+(y+h)+'" stroke="#1A6FC4" stroke-width="1"/>'+
      '<line x1="'+(x-23)+'" y1="'+y+'" x2="'+(x-13)+'" y2="'+y+'" stroke="#1A6FC4" stroke-width="1"/>'+
      '<line x1="'+(x-23)+'" y1="'+(y+h)+'" x2="'+(x-13)+'" y2="'+(y+h)+'" stroke="#1A6FC4" stroke-width="1"/>'+
      '<text x="'+(x-26)+'" y="'+(y+h/2)+'" text-anchor="middle" transform="rotate(-90 '+(x-26)+' '+(y+h/2)+')" font-family="IBM Plex Mono, monospace" font-size="11" fill="#003478">'+p.d+"'"+'</text>'+
      // caption
      '<text x="180" y="204" text-anchor="middle" font-family="IBM Plex Mono, monospace" font-size="10.5" fill="#5A6B82">'+p.label.toUpperCase()+' · '+p.plot.toLocaleString("en-US")+' SFT PLOT AREA</text>';
  }

  function render(){
    var a = state.area || 0;
    var ba = state.bmt ? (state.bmtArea || 0) : 0;
    var showG = (state.scope !== "finish");
    var showF = (state.scope !== "gray");

    var g  = a * GRAY,  f  = a * FIN;
    var bg = ba * BMT_GRAY, bf = ba * BMT_FIN;

    var grayPart = (showG ? g : 0) + (showG ? bg : 0);
    var finPart  = (showF ? f : 0) + (showF ? bf : 0);
    var total = grayPart + finPart;

    document.getElementById("oGray").textContent = showG ? rs(g) : "— not in scope";
    document.getElementById("oFin").textContent  = showF ? rs(f) : "— not in scope";

    document.getElementById("rowBmtG").hidden = !(state.bmt && showG);
    document.getElementById("rowBmtF").hidden = !(state.bmt && showF);
    document.getElementById("oBmtG").textContent = rs(bg);
    document.getElementById("oBmtF").textContent = rs(bf);

    document.getElementById("oArea").textContent = sft(a) + (state.bmt ? "  +  " + sft(ba) + " basement" : "");
    document.getElementById("oTotal").textContent = rs(total);

    var qty = (showG||showF) ? (a + (state.bmt ? ba : 0)) : 0;
    var blended = qty ? total/qty : 0;
    document.getElementById("oAlt").textContent = total
      ? (words(total) + "   ·   Rs " + Math.round(blended).toLocaleString("en-US") + " / SFT blended")
      : "";

    document.getElementById("totalLabel").textContent =
      state.scope === "gray" ? "Gray structure cost" :
      state.scope === "finish" ? "Finishing cost" : "Total construction cost";

    var gp = total ? grayPart/total*100 : 50;
    document.getElementById("barG").style.width = gp + "%";
    document.getElementById("barF").style.width = (100-gp) + "%";

    var dur = durationOf();
    document.getElementById("oDur").textContent = dur.total + " days";
    document.getElementById("oDurBreak").textContent =
      (state.scope === "gray"   ? dur.gray + " GRAY"
     : state.scope === "finish" ? dur.fin + " FINISHING"
     : dur.gray + " GRAY + " + dur.fin + " FINISHING")
     + (dur.bmt ? " + " + dur.bmt + " BASEMENT" : "")
     + "  ·  ≈ " + months(dur.total) + " MONTHS";

    renderPayments(total);

    document.getElementById("areaHint").textContent = state.custom
      ? "Custom covered area. Standard for " + state.plot.label + " is " + sft(state.plot.area) + "."
      : "Standard double-storey covered area for " + state.plot.label + ".";

    drawPlot(state.plot);
  }

  // ── payment schedule ──────────────────────────
  function renderPayments(total){
    var tb = document.getElementById("payBody");
    tb.innerHTML = "";
    var running = 0;
    PAYMENTS.forEach(function(m, i){
      var amt = (i === PAYMENTS.length - 1)
        ? Math.round(total) - running                 // last row absorbs rounding
        : Math.round(total * m.p / 100);
      running += amt;
      var tr = document.createElement("tr");
      tr.innerHTML = '<td class="num">'+m.n+'</td>'+
        '<td class="name" style="white-space:normal">'+m.s+'</td>'+
        '<td class="num">'+m.p+'%</td>'+
        '<td class="num">'+(total ? rs(amt) : "—")+'</td>';
      tb.appendChild(tr);
    });
    document.getElementById("payTotal").textContent = total ? rs(total) : "—";

    var scopeName = state.scope === "gray" ? "gray structure"
                  : state.scope === "finish" ? "finishing"
                  : "turnkey";
    document.getElementById("payBasis").textContent =
      "Based on a " + scopeName + " contract for " + sft(state.area || 0) +
      (state.bmt ? " plus a " + sft(state.bmtArea || 0) + " basement" : "") +
      " — " + rs(total) + " total. Adjust the estimator to reprice.";
  }

