    "The completion period stated above runs from the date of mobilisation and is subject to timely payments, timely approval of drawings and material selections, and force majeure events. Delays attributable to the client extend the programme day for day.",
    "Any variation or additional work must be approved in writing before execution and will be billed with the following instalment.",
    "Material brands are as per the approved schedule. All reinforcement steel is Grade 60 (60,000 psi). Equivalent alternates may be proposed and are subject to written approval.",
    "In the event of abnormal escalation in the price of cement, steel or other primary materials, rates shall be reviewed by mutual consent.",
    "A defects liability period of twelve months from the date of handover applies to workmanship.",
    "ACCO provides a 10-year structural warranty on the RCC frame structure — foundation, columns, beams and roof slab — from the date of handover, covering defects in structural design and workmanship. This warranty excludes damage from natural disasters, unauthorised structural alterations, additional loads not accounted for in the approved design, or lack of routine maintenance."
  ];

  function specRows(){
    var out = "";
    Object.keys(BRANDS).forEach(function(cat){
      out += '<tr><td class="k" colspan="2" style="background:#EAF1FA;font-family:\'IBM Plex Sans\',sans-serif;font-weight:700;' +
             'font-size:9.2px;letter-spacing:.07em;text-transform:uppercase">' + esc(cat) + '</td></tr>';
      BRANDS[cat].forEach(function(r){
        var vals = r.v.map(function(v){ return esc(v.split("|")[0]); }).join(", ");
        out += '<tr><td class="k">' + esc(r.t) + '</td><td>' + vals + '</td></tr>';
      });
    });
    return out;
  }

  var QREF = "";
  function buildQuote(){
    QREF = refNo();
    var a  = state.area || 0;
    var ba = state.bmt ? (state.bmtArea || 0) : 0;
    var showG = (state.scope !== "finish");
    var showF = (state.scope !== "gray");

    var g = a*GRAY, f = a*FIN, bg = ba*BMT_GRAY, bf = ba*BMT_FIN;
    var total = (showG ? g+bg : 0) + (showF ? f+bf : 0);

    var scopeName = state.scope === "gray" ? "Gray Structure Construction"
                  : state.scope === "finish" ? "Finishing Works"
                  : "Turnkey House Construction";

    var dur = durationOf();

    var client = document.getElementById("qClient").value.trim() || "—";
    var site   = document.getElementById("qSite").value.trim() || state.plot.label + " residential plot";

    // ── cost rows
    var rows = "", sr = 0;
    if(showG){
      sr++; rows += '<tr><td class="c">'+sr+'</td><td><b>Gray structure</b><br><span style="color:#5A6B82;font-size:9.6px">'+
        'Complete RCC structural shell — foundation to plastered roofed building</span></td>'+
        '<td class="n">'+Math.round(a).toLocaleString("en-US")+'</td><td class="n">2,850</td><td class="n">'+rs(g)+'</td></tr>';
    }
    if(showF){
      sr++; rows += '<tr><td class="c">'+sr+'</td><td><b>Standard finishing</b><br><span style="color:#5A6B82;font-size:9.6px">'+
        'Full finishing package to move-in condition</span></td>'+
        '<td class="n">'+Math.round(a).toLocaleString("en-US")+'</td><td class="n">2,800</td><td class="n">'+rs(f)+'</td></tr>';
    }
    if(state.bmt && showG){
      sr++; rows += '<tr><td class="c">'+sr+'</td><td><b>Basement — gray structure</b><br><span style="color:#5A6B82;font-size:9.6px">'+
        'Excavation, shoring, raft, retaining walls, waterproofing, slab</span></td>'+
        '<td class="n">'+Math.round(ba).toLocaleString("en-US")+'</td><td class="n">5,500</td><td class="n">'+rs(bg)+'</td></tr>';
    }
    if(state.bmt && showF){
      sr++; rows += '<tr><td class="c">'+sr+'</td><td><b>Basement — finishing</b><br><span style="color:#5A6B82;font-size:9.6px">'+
        'Floor finish, paint, doors, lighting, power, drainage, ventilation</span></td>'+
        '<td class="n">'+Math.round(ba).toLocaleString("en-US")+'</td><td class="n">2,800</td><td class="n">'+rs(bf)+'</td></tr>';
    }

    // ── payment rows
    var payRows = "", running = 0;
    PAYMENTS.forEach(function(m,i){
      var amt = (i === PAYMENTS.length-1) ? Math.round(total)-running : Math.round(total*m.p/100);
      running += amt;
      payRows += '<tr><td class="c">'+m.n+'</td><td>'+esc(m.s)+'</td><td class="n">'+m.p+'%</td><td class="n">'+rs(amt)+'</td></tr>';
    });

    var qtyTotal = a + (state.bmt ? ba : 0);
    var blended  = qtyTotal ? Math.round(total/qtyTotal) : 0;

    var html =
    '<div class="qhead">'+
      '<div class="lh">'+
        '<img src="'+LOGO+'" alt="Ahmed Construction Company">'+
        '<div class="co"><b>AHMED CONSTRUCTION COMPANY</b>'+
          '<span>Architecture &middot; Engineering &middot; Construction</span>'+
          'Office 2, 3rd Floor, Bigcity Plaza, Gulberg-III, Lahore<br>'+
          '0322-8000190 &nbsp;|&nbsp; info@acco.com.pk &nbsp;|&nbsp; acco.com.pk'+
          '<span class="qfor">Prepared for: '+esc(client)+'</span></div>'+
      '</div><div class="lh-rule"></div>'+
    '</div>'+

    '<div class="qtitle"><div><h1>Quotation — House Construction</h1>'+
      '<div class="sub">'+esc(scopeName)+' &middot; 2026 Rates</div></div>'+
      '<div class="qmeta"><b>Ref</b> '+QREF+'<br><b>Date</b> '+today()+'<br><b>Valid till</b> '+validTill()+'</div></div>'+

    '<div class="qto">'+
      '<div><div class="lbl">Quotation for</div><div class="val">'+esc(client)+'</div></div>'+
      '<div><div class="lbl">Project site</div><div class="val">'+esc(site)+'</div></div>'+
    '</div>'+

    '<div class="qsection"><h2><i>01</i> Project particulars</h2>'+
      '<table class="qt"><tbody>'+
        '<tr><td class="k" style="background:#F4F8FC;font-weight:600;color:#003478;width:26%">Plot size</td><td>'+esc(state.plot.label)+'</td>'+
            '<td class="k" style="background:#F4F8FC;font-weight:600;color:#003478;width:26%">Plot dimensions</td><td>'+state.plot.w+"' &times; "+state.plot.d+"'</td></tr>"+
        '<tr><td class="k" style="background:#F4F8FC;font-weight:600;color:#003478">Plot area</td><td>'+state.plot.plot.toLocaleString("en-US")+' SFT</td>'+
            '<td class="k" style="background:#F4F8FC;font-weight:600;color:#003478">Covered area</td><td><b>'+Math.round(a).toLocaleString("en-US")+' SFT</b></td></tr>'+
        '<tr><td class="k" style="background:#F4F8FC;font-weight:600;color:#003478">Basement area</td><td>'+(state.bmt ? '<b>'+Math.round(ba).toLocaleString("en-US")+' SFT</b>' : 'Not applicable')+'</td>'+
            '<td class="k" style="background:#F4F8FC;font-weight:600;color:#003478">Scope of contract</td><td><b>'+esc(scopeName)+'</b></td></tr>'+
        '<tr><td class="k" style="background:#F4F8FC;font-weight:600;color:#003478">Total billed area</td><td>'+Math.round(qtyTotal).toLocaleString("en-US")+' SFT</td>'+
            '<td class="k" style="background:#F4F8FC;font-weight:600;color:#003478">Blended rate</td><td>Rs '+blended.toLocaleString("en-US")+' / SFT</td></tr>'+
        '<tr><td class="k" style="background:#F4F8FC;font-weight:600;color:#003478">Completion period</td><td colspan="3"><b>'+dur.total+' days</b> from mobilisation &mdash; '+
            (showG ? dur.gray+' days gray structure' : '')+(showG&&showF ? ' + ' : '')+(showF ? dur.fin+' days finishing' : '')+
            (dur.bmt ? ' + '+dur.bmt+' days basement' : '')+' &nbsp;(&asymp; '+months(dur.total)+' months)</td></tr>'+
      '</tbody></table></div>'+

    '<div class="qsection"><h2><i>02</i> Cost summary</h2>'+
      '<table class="qt"><thead><tr><th class="c">SR</th><th>Description</th><th class="n">Area (SFT)</th>'+
      '<th class="n">Rate (Rs/SFT)</th><th class="n">Amount (Rs)</th></tr></thead>'+
      '<tbody>'+rows+
      '<tr class="grand"><td colspan="4">TOTAL CONTRACT VALUE</td><td class="n">'+rs(total)+'</td></tr>'+
      '</tbody></table>'+
      '<div class="inwords"><b>In words</b>'+inWords(total)+'</div></div>'+

    '<div class="qsection"><h2><i>03</i> Payment schedule</h2>'+
      '<table class="qt"><thead><tr><th class="c">SR</th><th>Scope of work</th><th class="n">%age</th><th class="n">Amount (Rs)</th></tr></thead>'+
      '<tbody>'+payRows+
      '<tr class="sub"><td class="c">—</td><td>TOTAL</td><td class="n">100%</td><td class="n">'+rs(total)+'</td></tr>'+
      '</tbody></table>'+
      '<div class="inwords" style="border-top:0"><b>Note</b>Each instalment falls due on completion of the stage against it, verified on site before invoicing. '+
      (state.bmt ? 'For the basement, the plinth and ground wall stages are read as basement raft, basement walls and basement slab.' : 'Mobilisation advance is payable on signing of the contract.')+'</div></div>'+

    '<div class="qsection"><h2><i>04</i> Project Timeline</h2>'+
      '<table class="qt"><thead><tr><th>Stage</th><th class="n">Duration</th><th>Remarks</th></tr></thead><tbody>'+
      (showG ? '<tr><td>Gray structure</td><td class="n">'+dur.gray+' days</td><td>Mobilisation to plastered, roofed, watertight structure</td></tr>' : '')+
      (showF ? '<tr><td>Standard finishing</td><td class="n">'+dur.fin+' days</td><td>Finishing trades to move-in condition and handover</td></tr>' : '')+
      (dur.bmt ? '<tr><td>Basement</td><td class="n">'+dur.bmt+' days</td><td>Added to the substructure programme</td></tr>' : '')+
      '<tr class="sub"><td>TOTAL PROJECT DURATION</td><td class="n">'+dur.total+' days</td><td>&asymp; '+months(dur.total)+' months from mobilisation</td></tr>'+
      '</tbody></table>'+
      '<div class="inwords" style="border-top:0"><b>Note</b>Durations are in calendar days and assume timely payments, timely approval of drawings and material selections, and normal weather. Finishing trades overlap the structural programme from the ground floor slab onward.</div></div>'+

    '<div class="qsection"><h2><i>05</i> Scope of work</h2>'+
      '<div class="qcols">'+
        '<div><h4>Gray structure'+(showG?'':' — not in this contract')+'</h4><ul class="qlist">'+
          GRAY_SCOPE.map(function(x){return '<li>'+esc(x)+'</li>';}).join('')+'</ul></div>'+
        '<div><h4>Standard finishing'+(showF?'':' — not in this contract')+'</h4><ul class="qlist">'+
          FIN_SCOPE.map(function(x){return '<li>'+esc(x)+'</li>';}).join('')+'</ul></div>'+
      '</div></div>'+

    '<div class="qsection"><h2><i>06</i> Material specification</h2>'+
      '<table class="spec"><tbody>'+specRows()+'</tbody></table>'+
      '<div class="inwords" style="border-top:0"><b>Note</b>Final brand selection within each approved category is made jointly with the client before procurement.</div></div>'+

    '<div class="qsection"><h2><i>07</i> Exclusions</h2>'+
      '<ol class="terms">'+EXCLUSIONS.map(function(x){return '<li>'+esc(x)+'</li>';}).join('')+'</ol></div>'+

    '<div class="qsection"><h2><i>08</i> Terms and conditions</h2>'+
      '<ol class="terms">'+TERMS.map(function(x){return '<li>'+esc(x)+'</li>';}).join('')+'</ol></div>'+

    '<div class="sign">'+
      '<div><div class="r">For Ahmed Construction Company</div><div class="s">Authorised signatory &nbsp;|&nbsp; Date</div></div>'+
      '<div><div class="r">Accepted by client</div><div class="s">Name, signature &amp; CNIC &nbsp;|&nbsp; Date</div></div>'+
    '</div>'+

    '<div class="qfoot"><span>Ahmed Construction Company (ACCO) &middot; Architecture, Engineering &amp; Construction &middot; 25+ years</span>'+
      '<span>This quotation supersedes all previous verbal or written estimates for this project.</span></div>';

    document.getElementById("quoteDoc").innerHTML = html;
  }

  function showQuote(show){
    document.body.classList.toggle("quote-mode", show);
    document.getElementById("site").hidden = show;
    document.getElementById("quoteWrap").hidden = !show;
    window.scrollTo(0,0);
  }

  document.getElementById("qGen").addEventListener("click", function(){
    buildQuote();
    showQuote(true);
  });
  document.getElementById("qBack").addEventListener("click", function(){ showQuote(false); });

  // filename used for both save actions
  function quoteFileName(){
    var c = document.getElementById("qClient").value.trim()
              .replace(/[^A-Za-z0-9 ]/g,"").replace(/\s+/g,"-");
    return c || QREF.replace(/[^A-Za-z0-9]/g,"-");
  }

  function needClient(){
    if(document.getElementById("qClient").value.trim()) return false;
    showQuote(false);
    var el = document.getElementById("qClient");
    el.focus();
    el.style.borderColor = "#0057B8";
    el.placeholder = "Enter client name — used for the file name";
    return true;
  }

  // Save as PDF — names the file via document.title, then opens the print dialog
  document.getElementById("qPrint").addEventListener("click", function(){
    if(needClient()) return;
    var t = document.title;
    document.title = quoteFileName();
    window.print();
    setTimeout(function(){ document.title = t; }, 1200);
  });

  // Save copy — downloads the quotation as a standalone HTML file
  document.getElementById("qSaveCopy").addEventListener("click", function(){
    if(needClient()) return;
    var css = "";
    Array.prototype.forEach.call(document.querySelectorAll("style"), function(s){ css += s.textContent + "\n"; });
    var doc = '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8">' +
      '<meta name="viewport" content="width=device-width, initial-scale=1">' +
      '<title>' + quoteFileName() + '</title>' +
      '<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@500;600;700;800&family=IBM+Plex+Mono:wght@400;500;600&family=IBM+Plex+Sans:wght@400;500;600&display=swap" rel="stylesheet">' +
      '<style>' + css +
        'body{margin:0;background:#E8EDF3}' +
        '@media print{@page{size:210mm 297mm portrait;margin:14mm 12mm 14mm 12mm}' +
        'html,body{background:#fff!important}.quote-stage{padding:0!important;background:#fff!important}' +
        '.quote-doc{width:auto!important;max-width:none!important;min-height:0!important;padding:0!important;box-shadow:none!important;font-size:10.2px}' +
        '.qhead{background:#fff}}' +
      '</style></head>' +
      '<body class="quote-mode"><div class="quote-stage"><div class="quote-doc">' +
      document.getElementById("quoteDoc").innerHTML +
      '</div></div></body></html>';
    var blob = new Blob([doc], {type:"text/html;charset=utf-8"});
    var url = URL.createObjectURL(blob);
    var a = document.createElement("a");
    a.href = url; a.download = quoteFileName() + ".html";
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(function(){ URL.revokeObjectURL(url); }, 4000);
  });

  render();
})();

</script>
</body>
</html>
